import { supabase } from 'services/supabaseClient';
import type { Job } from '../pages/Job';

async function fetchCategoryMap(): Promise<Map<string, string>> {
    const { data, error } = await supabase.from('job_categories').select('id, name');
    if (error) {
        console.warn('Supabase error (job_categories):', error);
        return new Map();
    }
    return new Map((data ?? []).map((row) => [row.id as string, row.name as string]));
}

function mapDBJobToJob(
    row: Record<string, unknown>,
    categoryMap: Map<string, string>,
): Job {
    const posted_by_user = (row.posted_by_user as Record<string, unknown> | null) ?? {};

    const categoriesId: string[] = Array.isArray(row.categories) ? (row.categories as string[]) : [];
    const categoryNames: string[] = categoriesId.map((id) => categoryMap.get(id)).filter((t): t is string => !!t);

    // Try to determine job type based on categories, job_location_type, or default.
    // The UI screenshot shows "Talent Acquisition Specialist", "Brand Manager" etc. for Job Type.
    // We'll use the first category name if available, otherwise just use the title temporarily as a fallback or "General".
    const jobType = categoryNames.length > 0 ? categoryNames[0] : 'General';

    return {
        id: (row.id as string) ?? '',
        jobId: ((row.id as string) ?? '').substring(0, 10).replace(/[^0-9]/g, '').padStart(10, '0'), // Fake job ID like 3543645757 for UI, since we just have a UUID
        title: (row.title as string) ?? '',
        jobType: jobType,
        status: (row.status as string) ?? 'pending',
        applicants: (row.applicants as number) ?? 0,
        posted_at: (row.posted_at as string | null) ?? null,

        // User relation
        posted_by_user_id: (row.posted_by_user_id as string) ?? null,
        posted_by_name: [posted_by_user.first_name, posted_by_user.last_name].filter(Boolean).join(' ') || 'Unknown',
        posted_by_image: (posted_by_user.image_url as string) ?? null,
    };
}

export const fetchJobs = async (): Promise<Job[]> => {
    const [categoryMap, jobsResult] = await Promise.all([
        fetchCategoryMap(),
        supabase.from('jobs').select(`
      *,
      posted_by_user:profiles!fk_posted_by_user(first_name, last_name, image_url)
    `).order('posted_at', { ascending: false }),
    ]);

    if (jobsResult.error) {
        console.error('Supabase error (jobs):', jobsResult.error);
        return [];
    }

    return (jobsResult.data ?? []).map((row) =>
        mapDBJobToJob(row as Record<string, unknown>, categoryMap)
    );
};
